fn solve(s: Vec<char>) -> Vec<char> {
    // Count occurrences of 'a', 'b', 'c' among the first three characters.
    // If any character is outside 'a'..='c' or any count exceeds 1, we can already return "No\n".
    let mut counts = [0; 3];
    for &ch in s.iter().take(3) {
        let idx = match ch {
            'a' => 0,
            'b' => 1,
            'c' => 2,
            _ => {
                // According to the problem statement this should not happen,
                // but if it does, it's not a valid permutation.
                return "No\n".chars().collect();
            }
        };
        counts[idx] += 1;
        if counts[idx] > 1 {
            // Duplicate found
            return "No\n".chars().collect();
        }
    }

    // If we have exactly one of each, it's a permutation of {'a','b','c'}.
    if counts == [1, 1, 1] {
        "Yes\n".chars().collect()
    } else {
        "No\n".chars().collect()
    }
}